with valid as (select *, date_format(opened_date, 'MMM yyyy') as opened_date_label, case when sqft >= 12932 then 'High' when sqft >= 3630 then 'Medium' else 'Low' end as sqft_level, coalesce(region, 'OTHER') as region_filled from stores where opened_date >= date '2023-05-27' and region is not null) select *, dense_rank() over (order by sqft) as sqft_dense_rank, max(sqft) over (partition by region, city) as region_max_sqft, lag(sqft, 1) over (partition by city order by opened_date, id) as prev_sqft from valid;
